class Solution {
    unordered_map<string, vector<char>> mapping;
    unordered_set<string> memo;
    bool solve(const string& row) {
        if (row.size() == 1) return true;
        if (memo.count(row)) return false;

        string nextRow = "";
        function<bool(int)> buildNext = [&](int idx) {
            if (idx == row.size() - 1) return solve(nextRow);
            string pair = row.substr(idx, 2);
            if (!mapping.count(pair)) return false;
            for (char top : mapping[pair]) {
                nextRow.push_back(top);
                if (buildNext(idx + 1)) return true;
                nextRow.pop_back();
            }
            return false;
        };

        bool res = buildNext(0);
        if (!res) memo.insert(row);
        return res;
    }
public:
