    }
};

class Solution {
    private Map<String, List<Character>> mapping = new HashMap<>();
    private Set<String> memo = new HashSet<>();
    public boolean pyramidTransition(String bottom, List<String> allowed) {
        for (String s : allowed) {
            String key = s.substring(0, 2);
            mapping.computeIfAbsent(key, k -> new ArrayList<>()).add(s.charAt(2));
        }
        return solve(bottom);
    }
    private boolean solve(String row) {
        if (row.length() == 1) return true;
        if (memo.contains(row)) return false;
        boolean res = buildNext(row, 0, new StringBuilder());
        if (!res) memo.add(row);
        return res;
    }
    private boolean buildNext(String row, int idx, StringBuilder nextRow) {
        if (idx == row.length() - 1) return solve(nextRow.toString());
        String pair = row.substring(idx, idx + 2);
        if (!mapping.containsKey(pair)) return false;
        for (char top : mapping.get(pair)) {
            nextRow.append(top);
            if (buildNext(row, idx + 1, nextRow)) return true;
            nextRow.deleteCharAt(nextRow.length() - 1);
        }
        return false;
    }
}

var pyramidTransition = function(bottom, allowed) {
    const mapping = new Map();
    for (const s of allowed) {
        const key = s.slice(0, 2);
        if (!mapping.has(key)) mapping.set(key, []);
        mapping.get(key).push(s[2]);
    }
    const memo = new Set();

    function solve(row) {
        if (row.length === 1) return true;
        if (memo.has(row)) return false;

        function buildNext(idx, cur) {
            if (idx === row.length - 1) return solve(cur.join(''));
            const pair = row.slice(idx, idx + 2);
            const tops = mapping.get(pair) || [];
            for (const top of tops) {
                cur.push(top);
                if (buildNext(idx + 1, cur)) return true;
                cur.pop();
            }
            return false;
        }

        const res = buildNext(0, []);
        if (!res) memo.add(row);
        return res;
    }

    return solve(bottom);
};
